+        RelHint stateTtlHintOuter =
+                RelHint.builder("StAte_tTl").hintOptions(hintOptionsOuter).build();
+
+        RelHint aliasHint = RelHint.builder(FlinkHints.HINT_ALIAS).hintOption("t4").build();
