+                userValueSerializer.serialize(userValue, outputSerializer);
+                userValueSize = outputSerializer.length();
+            } finally {
+                outputSerializer.clear();
+            }
+        } else {
+            userValueSize = userValueSerializer.getLength();
+        }
+        return userValueSize;
